__NUXT_JSONP__("/desarrollo-sostenible/eventos/latinoamerica_sostenible_comparte_experiencias_de_resiliencia_y_transicion_justa_en_comunidades_de_la_region", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{post:{slug:"latinoamerica_sostenible_comparte_experiencias_de_resiliencia_y_transicion_justa_en_comunidades_de_la_region",title:"Latinoamérica Sostenible comparte experiencias de resiliencia y transición justa en comunidades de la región",date:"2023-10-12T17:46:42.676Z",img:"https:\u002F\u002Fucarecdn.com\u002F958e0da6-f2d3-47d6-aa6e-93d5676898cc\u002F","img-alt":"Latinoamérica Sostenible",autor:"Ethos",category:"desarrollo-sostenible",extracto:"La alianza de las organizaciones Transforma (Colombia), Ethos (México) y Espacio Público (Chile)  presentó el trabajo realizado junto a tres organizaciones comunitarias con enfoque en mujeres, comunidades indígenas y empleos verdes, que fueron parte del proyecto “Recuperación justa y resiliente de nuestras comunidades ante el COVID-19” durante 2022 y 2023.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La pandemia generada por el COVID-19 impactó en distintas dimensiones a la población de América Latina y el Caribe, especialmente a grupos más vulnerables. En ese escenario, desde 2020 la alianza Latinoamérica Sostenible ha desarrollado diversos análisis en torno a cómo generar una recuperación económica que considere el contexto de crisis múltiple que vivimos y la importancia de impulsar empleos verdes, promoviendo una transición justa y el fortalecimiento de la resiliencia comunitaria."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Por ello, en el seminario "},{type:b,tag:"strong",props:{},children:[{type:a,value:"“Transición justa y resiliencia en comunidades de América Latina”,"}]},{type:a,value:" realizado el jueves 12 de octubre y organizado junto a Rimisp – Centro Latinoamericano para el Desarrollo Rural y la Plataforma para una Reactivación Sostenible (PLARS), se compartió la experiencia de tres agrupaciones territoriales que formaron parte del proyecto “Recuperación justa y resiliente de nuestras comunidades ante el COVID-19”, impulsado por la alianza Latinoamérica Sostenible durante 2022 y 2023. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Así, durante el primer panel de conversación, Vladimir Vicencio, miembro de la oficina de Asuntos Hídricos de la Municipalidad de Petorca (Chile); Saúl Galeano, representante legal de la Corporación Comunitaria de Prestadores de Servicios Turísticos de la Serranía de la Lindosa y del Guaviare (Colombia) y Merced González Cruz, facilitadora de la Agencia de Desarrollo Rural Sierra Norte (México) explicaron sus experiencias en el trabajo con comunidades de mujeres, indígenas y rurales, y las lecciones aprendidas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el segundo panel de conversación, se abordó la importancia de fortalecer liderazgos en las comunidades y desarrollar estrategias que aumenten su resiliencia. Así, Rodrigo Yañez, director Oficina Chile de Rimisp; Diego Saavedra, líder de proyectos de Derecho, Ambiente y Recursos Naturales (DAR)-PLARS y Laure Delalande, directora de Inclusión y Desarrollo Sostenible de Ethos-Latinoamérica Sostenible, abordaron los contextos de constantes crisis a las que nos hemos visto y veremos enfrentados como región, y cómo el concepto de “resiliencia comunitaria” es fundamental para poder avanzar hacia una real adaptación al cambio climático."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Finalmente, el tercer panel se centró en los desafíos para alcanzar una transición justa en las comunidades. Juliana Peña, Senior Officer para América Latina del Natural Resource Governance Institute (NRGI)-PLARS; José Navea, Investigador en seguridad alimentaria, hídrica y energética de RIMISP y Rodrigo Guerrero, investigador de Medio Ambiente y Sustentabilidad de Espacio Público-Latinoamérica Sostenible profundizaron en cómo lograr equilibrios y equidad social en los países de la región, con sus distintos escenarios y realidades  territoriales. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Los diálogos fueron moderados por Ana Mogollón, coordinadora de recuperación y transición energética de Transforma-Latinoamérica Sostenible."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Si te perdiste el seminario, puedes volver a verlo "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.youtube.com\u002Fwatch?v=2L1gZKicwkQ",rel:[f,g,h],target:i},children:[{type:a,value:"aquí"}]},{type:a,value:". Para más información sobre el trabajo de la alianza Latinoamérica Sostenible, ingresa a "},{type:b,tag:e,props:{href:"http:\u002F\u002Fwww.latinoamericasostenible.org",rel:[f,g,h],target:i},children:[{type:a,value:"www.latinoamerica sostenible.org"}]}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Flatinoamerica_sostenible_comparte_experiencias_de_resiliencia_y_transicion_justa_en_comunidades_de_la_region",extension:".md",createdAt:j,updatedAt:j}}],fetch:{},mutations:[]}}("text","element","p","\n","a","nofollow","noopener","noreferrer","_blank","2023-10-20T17:10:25.802Z")));